//! Exact retained Omega replay under the independently installed source authority.
//!
//! Inputs are pinned genuine exchange originals. No fixture, proof, wallet session
//! or replacement original is generated by this read-only verification harness.

use super::*;
use crate::kagemusha_wallet_proofs_v1::{
    Error as ProofError, KagemushaWalletVerificationCountsV1 as Counts, lineage_public_fields,
};
use ff::PrimeField as _;
use iroha_data_model::kagemusha::{
    KagemushaWalletLineageV1, KagemushaWalletVerifyingKeyAllowlistV1, kagemusha_wallet_poseidon_v1,
};
use iroha_pasta::{Ep, Eq, Fq};
use iroha_plonk::{DescriptorBinding, Protocol, VerifyingKey};
use iroha_plonk_recursion::{ACCUMULATOR_BYTES, AccumulatorT};

// Test-owned reconstruction observes the installed input without adding a public
// restore API or accepting caller-chosen instance columns in production.
fn instances(
    lineage: &KagemushaWalletLineageV1,
    key_digest: [u8; 32],
    pallas: &AccumulatorT<Ep>,
    vesta: &AccumulatorT<Eq>,
) -> Vec<Vec<Fq>> {
    let mut words = lineage_public_fields(&lineage.public, key_digest)
        .unwrap()
        .map(|word| word.to_repr())
        .to_vec();
    let (x, y) = iroha_plonk::transcript::generator_coordinates::<Ep>(pallas.g());
    words.extend([x.to_repr(), y.to_repr()]);
    for challenge in pallas.challenges() {
        let bytes = challenge.to_repr();
        let mut low = [0; 32];
        let mut high = [0; 32];
        low[..16].copy_from_slice(&bytes[..16]);
        high[..16].copy_from_slice(&bytes[16..]);
        words.extend([low, high]);
    }
    let digest = kagemusha_wallet_poseidon_v1(u64::from_le_bytes(*b"kgwomg_1"), &words).unwrap();
    let (x, y) = iroha_plonk::transcript::generator_coordinates::<Eq>(vesta.g());
    vec![
        vec![Option::<Fq>::from(Fq::from_repr(digest)).unwrap()],
        vec![x, y],
        vesta
            .challenges()
            .iter()
            .map(|value| Option::<Fq>::from(Fq::from_repr(value.to_repr())).unwrap())
            .collect(),
    ]
}

fn check_original(sources: &Sources, expected: &KagemushaWalletLineageV1) {
    let verifier = sources.installed.verifier();
    let mounted = sources.installed.originals();
    let installation_bytes = sources.installed.original().to_vec();
    assert_eq!(
        sources.qualified.installation(),
        (verifier.scheme().scheme_id(), verifier.manifest_digest())
    );
    assert_eq!(expected.public.scheme_id, verifier.scheme().scheme_id());
    assert_eq!(expected.public.relation_id, verifier.scheme().relation_id);
    let binding = DescriptorBinding::decode_v2(&mounted.lineage.descriptor).unwrap();
    let key = VerifyingKey::<Ep>::read(&mounted.lineage.verifying_key, &binding).unwrap();
    let allowlist: KagemushaWalletVerifyingKeyAllowlistV1 = decode(&mounted.allowlist);
    let key_digest = key.kagemusha_digest(&binding).unwrap().to_repr();
    assert_eq!(key_digest, allowlist.lineage_verifying_key_digest);
    let proof_bytes = Protocol::new(binding.descriptor()).unwrap().proof_length();
    assert_eq!(expected.proof.len(), proof_bytes + 2 * ACCUMULATOR_BYTES);
    assert_eq!(expected.proof.len() as u32, allowlist.lineage_proof_bytes);
    let original = norito::encode_canonical(expected).unwrap();
    let (proof, claims) = expected.proof.split_at(proof_bytes);
    let (p, v) = claims.split_at(ACCUMULATOR_BYTES);
    let pallas = AccumulatorT::<Ep>::from_bytes(p).unwrap();
    let vesta = AccumulatorT::<Eq>::from_bytes(v).unwrap();
    let public = instances(expected, key_digest, &pallas, &vesta);
    let opening = iroha_plonk::verifier::verify_full_opening_cancellable(
        verifier.pallas_parameters(),
        &binding,
        &key,
        &public,
        proof,
        MemoryBudget::DEFAULT,
        None,
    )
    .unwrap();
    pallas
        .decide(verifier.pallas_parameters(), MemoryBudget::DEFAULT)
        .unwrap();
    vesta
        .decide(
            verifier.vesta_parameters(16).unwrap(),
            MemoryBudget::DEFAULT,
        )
        .unwrap();

    // The baseline above observes the complete expected original and warms exactly
    // its verified-opening memo. Each installed replay must still visit both P/V
    // obligations and recompute its public binding, even on that memo hit.
    for _ in 0..2 {
        let replay: KagemushaWalletLineageV1 = decode(&original);
        assert_eq!(&replay, expected);
        let (accepted, work) = Counts::observe(|| {
            verifier.verify_lineage_cancellable(&replay, MemoryBudget::DEFAULT, None)
        });
        assert_eq!(accepted, Ok(()));
        assert_eq!(work.verify_lineage, 1);
        assert_eq!(work.proofs.verify_full, 1);
        assert_eq!(work.proofs.reused_verifications, 1);
        assert_eq!(
            work.proofs.decides, 2,
            "both transported claims still decide"
        );
        let (replay_proof, claims) = replay.proof.split_at(proof_bytes);
        let (rp, rv) = claims.split_at(ACCUMULATOR_BYTES);
        let rp = AccumulatorT::<Ep>::from_bytes(rp).unwrap();
        let rv = AccumulatorT::<Eq>::from_bytes(rv).unwrap();
        assert_eq!(replay_proof, proof);
        assert_eq!(rp, pallas);
        assert_eq!(rv, vesta);
        let replay_public = instances(&replay, key_digest, &rp, &rv);
        assert_eq!(replay_public, public);
        let replay_opening = iroha_plonk::verifier::verify_full_opening_cancellable(
            verifier.pallas_parameters(),
            &binding,
            &key,
            &replay_public,
            replay_proof,
            MemoryBudget::DEFAULT,
            None,
        )
        .unwrap();
        assert_eq!(replay_opening.g(), opening.g());
        assert_eq!(replay_opening.challenges(), opening.challenges());
        assert_eq!(replay_opening.k(), opening.k());
        assert_eq!(replay.proof, expected.proof);
        assert_eq!(norito::encode_canonical(&replay).unwrap(), original);
    }
    let cancellation = iroha_pasta::CancellationToken::new();
    cancellation.cancel();
    assert_eq!(
        verifier.verify_lineage_cancellable(expected, MemoryBudget::DEFAULT, Some(&cancellation)),
        Err(ProofError::Cancelled),
    );
    let mut truncated = expected.clone();
    truncated.proof.pop();
    let mut trailing = expected.clone();
    trailing.proof.push(0);
    let mut corrupt = expected.clone();
    corrupt.proof[0] ^= 1;
    for changed in [truncated, trailing, corrupt] {
        assert!(
            verifier
                .verify_lineage_cancellable(&changed, MemoryBudget::DEFAULT, None)
                .is_err()
        );
    }
    // Full-group canonical substitutions remain distinct even if the original G
    // is identity. Keep the expected lineage public words and source unchanged.
    let foreign_p = AccumulatorT::<Ep>::new(
        *verifier
            .pallas_parameters()
            .params()
            .g()
            .iter()
            .find(|point| *point != pallas.g())
            .unwrap(),
        *pallas.challenges(),
    )
    .unwrap();
    let foreign_v = AccumulatorT::<Eq>::new(
        *verifier
            .vesta_parameters(16)
            .unwrap()
            .params()
            .g()
            .iter()
            .find(|point| *point != vesta.g())
            .unwrap(),
        *vesta.challenges(),
    )
    .unwrap();
    assert_eq!(
        AccumulatorT::<Ep>::from_bytes(&foreign_p.to_bytes()).unwrap(),
        foreign_p
    );
    assert_eq!(
        AccumulatorT::<Eq>::from_bytes(&foreign_v.to_bytes()).unwrap(),
        foreign_v
    );
    for (offset, replacement) in [
        (proof_bytes, foreign_p.to_bytes()),
        (proof_bytes + ACCUMULATOR_BYTES, foreign_v.to_bytes()),
    ] {
        let mut changed = expected.clone();
        assert_ne!(
            &changed.proof[offset..offset + ACCUMULATOR_BYTES],
            replacement.as_slice()
        );
        changed.proof[offset..offset + ACCUMULATOR_BYTES].copy_from_slice(&replacement);
        assert_eq!(changed.public, expected.public);
        assert!(
            verifier
                .verify_lineage_cancellable(&changed, MemoryBudget::DEFAULT, None)
                .is_err()
        );
    }
    let mut wrong_lineage = expected.clone();
    wrong_lineage.public.burned_total ^= 1;
    wrong_lineage.public.validate().unwrap();
    assert_ne!(
        instances(&wrong_lineage, key_digest, &pallas, &vesta),
        public
    );
    assert!(
        verifier
            .verify_lineage_cancellable(&wrong_lineage, MemoryBudget::DEFAULT, None)
            .is_err()
    );
    assert_eq!(
        verifier.verify_lineage_cancellable(expected, MemoryBudget::DEFAULT, None),
        Ok(())
    );
    assert_eq!(norito::encode_canonical(expected).unwrap(), original);
    assert_eq!(sources.installed.original(), installation_bytes);
}

#[test]
#[ignore = "read-only genuine Omega replay; requires independently pinned current source and exchange originals"]
fn installed_omega_replay_preserves_originals_and_rejects_foreign_transport() {
    let output = fresh_output("KAGEMUSHA_NATIVE_OMEGA_REPLAY_OUTPUT");
    let sources = Sources::admit(&output.join("source-admission"));
    let input = selected_path("KAGEMUSHA_NATIVE_MESSAGE_ORIGINALS");
    let original = read_pin(
        &input,
        TARGET_MAX,
        &env_pin("KAGEMUSHA_NATIVE_MESSAGE_ORIGINALS_SHA256"),
    );
    let manifest: norito::json::Value = norito::json::from_slice(&original).unwrap();
    assert_eq!(
        manifest["schema"].as_str(),
        Some("iroha.kagemusha.message-originals.v1")
    );
    assert_eq!(manifest["source_pins"], source_pins());
    let rows = manifest["originals"].as_array().unwrap();
    assert_eq!(rows.len(), 4);
    let files = norito::json!({"files": (rows.clone())});
    for name in ["a-b-payment.norito", "b-c-payment.norito"] {
        let original = target_original(input.parent().unwrap(), &files, name, 10_034);
        let payment: KagemushaWalletPaymentV1 = decode(&original);
        let expected = payment
            .send
            .lineage
            .lineage()
            .expect("retained Send predecessor Omega");
        check_original(&sources, expected);
        assert_eq!(norito::encode_canonical(&payment).unwrap(), original);
    }
    publish(&output.join("result.json"), &norito::json::to_vec(&norito::json!({
        "schema": "iroha.kagemusha.omega-original-replay.v1",
        "originals_manifest_sha256": (sha(&original)),
        "source_pins": (source_pins()),
        "observer_binary_sha256": (executable_hash()),
        "accepted_originals": 2,
        "repeated_installed_replays": 4,
        "fresh_proofs": 0,
        "physical_device_qualified": false,
        "scope": "Installed source and expected-lineage binding, exact retained bytes/instances/P/V/own opening, cancelled/truncated/trailing/corrupt/foreign controls. Read-only retained evidence; no fresh wallet or release qualification."
    })).unwrap());
}
